{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "The Fire and the Fine Print",
      "goal": "Establish Rhea's death, her arrival in the Ledger's frontier tutorial, and her immediate realization that the system's 'mercy' mechanics are rigged. She finds her first loophole to survive the initial drop.",
      "chapter_role": "hook",
      "stakes_shift": "From confused victim of a fatal fire to an active participant in a rigged metaphysical economy.",
      "bridge": {
        "from_prev": "",
        "to_next": "Having survived the drop, Rhea must now navigate the basic survival economy using her newly discovered exploit mindset."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 4
      }
    },
    {
      "chapter_id": 2,
      "title": "Tariffs and Teeth",
      "goal": "Rhea navigates the frontier's predatory starter town, analyzing tariffs, cooldowns, and quest conditions to secure basic necessities without falling into the intended debt traps.",
      "chapter_role": "setup",
      "stakes_shift": "From immediate physical survival to economic stability and avoiding systemic debt.",
      "bridge": {
        "from_prev": "Rhea enters the settlement with minimal resources but a sharp eye for rule wording.",
        "to_next": "Securing a foothold attracts the attention of others trapped in or profiting from the same loop."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 5
      }
    },
    {
      "chapter_id": 3,
      "title": "Administrative Residue",
      "goal": "Rhea forms a reluctant partnership with a local clerk figure, pooling resources and uncovering administrative residue that hints at deeper systemic corruption.",
      "chapter_role": "alliance",
      "stakes_shift": "From solo survival to managing the liabilities and benefits of a fragile alliance.",
      "bridge": {
        "from_prev": "Rhea's unusual success rate in the starter economy makes her a target for both recruitment and exploitation.",
        "to_next": "The combined access of Rhea and her new ally allows them to see the hidden math behind the frontier's quest payouts."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 5
      }
    },
    {
      "chapter_id": 4,
      "title": "Auditing the Skim",
      "goal": "Rhea audits a standard progression quest, proving mathematically that experience and loot are being systematically skimmed by an unseen administrative layer.",
      "chapter_role": "investigation",
      "stakes_shift": "From suspecting the system is unfair to possessing concrete proof of institutional theft.",
      "bridge": {
        "from_prev": "Armed with administrative clues, Rhea actively tests the system's boundaries.",
        "to_next": "Possessing proof of the skim makes Rhea a threat to the local authorities profiting from it."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 5
      }
    },
    {
      "chapter_id": 5,
      "title": "Margin Calls",
      "goal": "Rhea pushes an exploit too far, triggering an automated audit and drawing the direct ire of the frontier's overseers, forcing her to defend her gains through bureaucratic and tactical combat.",
      "chapter_role": "pressure",
      "stakes_shift": "From flying under the radar to being actively hunted by local administrative enforcers.",
      "bridge": {
        "from_prev": "Rhea's continued exploitation of the skim creates a noticeable deficit in the overseers' ledgers.",
        "to_next": "The overseers escalate from warnings to direct, lethal debt-collection tactics."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 6
      }
    },
    {
      "chapter_id": 6,
      "title": "Weaponized Debt",
      "goal": "Rhea and her allies are cornered by the frontier authorities, who attempt to crush them using weaponized debt logic and rigged system mechanics. Rhea must find a counter-loophole to survive.",
      "chapter_role": "trial",
      "stakes_shift": "From evading capture to facing systemic execution via manufactured debt.",
      "bridge": {
        "from_prev": "The local power structure traps Rhea in a seemingly inescapable administrative snare.",
        "to_next": "Surviving the trap gives Rhea the leverage needed to strike back at the frontier's core infrastructure."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "steady",
        "expected_scene_count": 5
      }
    },
    {
      "chapter_id": 7,
      "title": "Systemic Feedback",
      "goal": "Rhea launches a counter-audit, exploiting a critical flaw in the frontier's core Ledger node to crash the local skimming operation, securing massive progression gains and administrative access.",
      "chapter_role": "climax",
      "stakes_shift": "From desperate defense to dismantling the local power structure and seizing its hoarded value.",
      "bridge": {
        "from_prev": "Rhea uses the evidence of the overseers' own rule-breaking to trigger a catastrophic system feedback loop.",
        "to_next": "The collapse of the frontier node forces Rhea to flee before higher-tier Ledger authorities arrive."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 6
      }
    },
    {
      "chapter_id": 8,
      "title": "Severance Package",
      "goal": "Rhea processes her massive progression gains, solidifies her build, and escapes the collapsing frontier zone, setting her sights on the institutional corruption of the wider civic world.",
      "chapter_role": "transition",
      "stakes_shift": "From conquering the tutorial zone to entering a vastly more dangerous, institutionally corrupt wider world.",
      "bridge": {
        "from_prev": "The frontier is broken, and Rhea holds the stolen administrative keys.",
        "to_next": "Rhea enters the city, ready to audit the true masters of the Ledger."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 4
      }
    }
  ]
}

